import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class ComparatorDemo {
    static class Product {
        final String name;
        final double price;
        final double rating;

        Product(String name, double price, double rating) {
            this.name = name;
            this.price = price;
            this.rating = rating;
        }

        public String getName() { return name; }
        public double getPrice() { return price; }
        public double getRating() { return rating; }

        @Override
        public String toString() {
            return String.format("%-12s: $%.2f (★%.1f)", name, price, rating);
        }
    }

    public static void main(String[] args) {
        List<Product> catalog = new ArrayList<>(List.of(
            new Product("Keyboard", 89.99, 4.5),
            new Product("Mouse", 29.99, 4.8),
            new Product("Headset", 89.99, 4.9),
            new Product("Mousepad", 15.00, 4.2)
        ));

        // Pipeline: Sort by price ascending; tie-break by rating descending
        Comparator<Product> bestDeal = Comparator
            .comparingDouble(Product::getPrice)
            .thenComparing(Comparator.comparingDouble(Product::getRating).reversed());

        catalog.sort(bestDeal);

        System.out.println("Best Deal Catalog:");
        for (Product p : catalog) {
            System.out.println(" -> " + p);
        }
    }
}
// Expected Output:
// Best Deal Catalog:
//  -> Mousepad    : $15.00 (★4.2)
//  -> Mouse       : $29.99 (★4.8)
//  -> Headset     : $89.99 (★4.9)
//  -> Keyboard    : $89.99 (★4.5)

