import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class NullSafeProfileSorter {
    static class Profile {
        final String department;
        final String username;

        Profile(String department, String username) {
            this.department = department;
            this.username = username;
        }

        public String getDepartment() { return department; }
        public String getUsername() { return username; }

        @Override
        public String toString() { return "[" + department + "/" + username + "]"; }
    }

    public static void main(String[] args) {
        List<Profile> profiles = new ArrayList<>();
        profiles.add(new Profile("Engineering", "Alice"));
        profiles.add(new Profile(null, "GhostUser"));
        profiles.add(new Profile("Engineering", "Bob"));
        profiles.add(new Profile("Analytics", "Charlie"));

        // Comparator: null departments placed last, case-insensitive
        Comparator<Profile> comp = Comparator
            .comparing(Profile::getDepartment, Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER))
            .thenComparing(Profile::getUsername);

        profiles.sort(comp);
        System.out.println("Sorted profiles:");
        for (Profile p : profiles) {
            System.out.println(" -> " + p);
        }
    }
}

