import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

public class FlightSorter {
    public static class Flight {
        final String flightNumber;
        final double price;
        final int durationMinutes;

        public Flight(String fn, double price, int duration) {
            this.flightNumber = fn;
            this.price = price;
            this.durationMinutes = duration;
        }
        public double getPrice() { return price; }
        public int getDurationMinutes() { return durationMinutes; }
        @Override public String toString() { return flightNumber; }
    }

    public static void sortFlights(List<Flight> flights) {
        if (flights == null) return;
        flights.sort(
            Comparator.comparingDouble(Flight::getPrice)
                      .thenComparingInt(Flight::getDurationMinutes)
        );
    }

    public static void main(String[] args) {
        List<Flight> flights = new ArrayList<>(List.of(
            new Flight("F1", 250.0, 180),
            new Flight("F2", 150.0, 120),
            new Flight("F3", 150.0, 90)
        ));
        sortFlights(flights);
        System.out.println(flights);
    }
}

