import java.util.Comparator;
import java.util.List;
import java.util.ArrayList;

public class ComparatorInverter {
    public static <T> Comparator<T> invert(Comparator<T> comp) {
        if (comp == null) return null;
        return comp.reversed();
    }

    public static void main(String[] args) {
        Comparator<Integer> natural = Integer::compare;
        Comparator<Integer> reversed = invert(natural);
        List<Integer> nums = new ArrayList<>(List.of(1, 4, 2));
        nums.sort(reversed);
        System.out.println(nums);
    }
}

