import java.util.*;

public class FrequencyValueSorter {
    public static void sortByFrequency(List<Integer> nums) {
        if (nums == null || nums.size() <= 1) return;
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int n : nums) {
            freqMap.put(n, freqMap.getOrDefault(n, 0) + 1);
        }

        nums.sort(
            Comparator.<Integer>comparingInt(freqMap::get).reversed()
                      .thenComparing(Comparator.naturalOrder())
        );
    }

    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>(List.of(4, 5, 6, 5, 4, 3));
        sortByFrequency(nums);
        System.out.println(nums);
    }
}
